function prepareInvoiceReminderSettings({ spreadsheetId, sheetName, timeZone }) {
  for (const [key, value] of Object.entries({ spreadsheetId, sheetName, timeZone })) if (typeof value !== 'string' || !value.trim() || value.includes('YOUR_')) throw new Error('Configure ' + key + '.');
  if (!/^[a-zA-Z0-9_-]+$/.test(spreadsheetId)) throw new Error('Use your Google spreadsheet ID.');
  const now = new Date(), parts = new Intl.DateTimeFormat('en-US', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(now), get = name => parts.find(part => part.type === name).value;
  const today = get('year') + '-' + get('month') + '-' + get('day');
  return { spreadsheetId: spreadsheetId.trim(), sheetName, range: "'" + sheetName.replaceAll("'", "''") + "'", timeZone, today };
}

