function sheetTable({ values, majorDimension = "ROWS" }) {
  if (majorDimension !== "ROWS" || !Array.isArray(values) || values.some((row) => !Array.isArray(row)))
    throw Error("Google Sheets must return row-oriented cell values.");
  const isEmpty = (value) => value == null || value === "", nonempty = (row) => row.some((value) => !isEmpty(value)), headerIndex = values.findIndex(nonempty);
  if (headerIndex < 0)
    return { columns: [], records: [] };
  const headers = values[headerIndex];
  if (headers.some((name) => typeof name !== "string" || !name.trim() || name === "row_number") || new Set(headers).size !== headers.length)
    throw Error("Use unique nonempty text headers; row_number is reserved.");
  const columns = ["row_number", ...headers], records = [];
  for (let index = headerIndex + 1;index < values.length; index++) {
    const cells = values[index];
    if (!nonempty(cells))
      continue;
    if (cells.slice(headers.length).some((value) => !isEmpty(value)))
      throw Error("Every populated column needs a header.");
    records.push(Object.fromEntries([["row_number", index + 1], ...headers.map((name, column) => [name, cells[column] ?? ""])]));
  }
  return { columns, records };
}
