function verifyInvoiceReminderLog({ spreadsheetId, expectedSpreadsheetId, totalUpdatedCells, responses, data, reminder, messageId }) {
  const cell = value => {
    if (typeof value !== 'string') return null;
    const match = /^('(?:[^']|'')+'|[^!]+)!\$?([A-Z]+)\$?(\d+)(?::\$?([A-Z]+)\$?(\d+))?$/.exec(value);
    if (!match || (match[4] && (match[4] !== match[2] || match[5] !== match[3]))) return null;
    const sheet = match[1].startsWith("'") ? match[1].slice(1, -1).replaceAll("''", "'") : match[1];
    return JSON.stringify([sheet, match[2], Number(match[3])]);
  };
  const sameCell = (first, second) => cell(first) !== null && cell(first) === cell(second);
  if (spreadsheetId !== expectedSpreadsheetId || totalUpdatedCells !== 2 || !Array.isArray(responses) || responses.length !== 2 || responses.some((response, index) => response.updatedCells !== 1 || !sameCell(response.updatedRange, data[index].range) || !sameCell(response.updatedData?.range, data[index].range) || response.updatedData?.values?.length !== 1 || response.updatedData.values[0]?.length !== 1 || response.updatedData.values[0][0] !== data[index].values[0][0])) throw new Error('Google Sheets did not confirm both reminder log cells.');
  return { receipt: { InvoiceID: reminder.InvoiceID, tier: reminder.tier, date: reminder.date, messageId } };
}

return $input.all().map((item,index)=>{const previous=$("Prepare Two Reminder Log Cells").itemMatching(index).json;return {json:verifyInvoiceReminderLog({...item.json,expectedSpreadsheetId:previous.spreadsheetId,data:previous.data,reminder:previous.reminder,messageId:previous.messageId}),pairedItem:{item:index}};});
